import './App.css';
import { useEffect, axios } from 'react';
import Festval_serch_details from "./component/Festval_serch_details.js";
import Festval_list_card from "./component/Festval_list_card.js";

const App= () => {  

  const Loging = async() => {
    const baseUrl = "http://apis.data.go.kr/B551011/KorService1/searchFestival1";
    const serviceKey = "";
    // const serviceKey = "Av0j4qFKXlogzFTNST8uPV8AmR6bdc5h9gNecQv1RR7v92yhfpCYFHj19OoN6mlq00fxLxYyEif4u5cu2GP%2BQA%3D%3D";
    const MobileOS = "ETC";
    const MobileApp = "Nado";
    const eventStartDate = "20241101";
    const type = "json";

    try{
      const response = await axios.get(baseUrl+"?serviceKey="+serviceKey+"&MobileOS="+MobileOS+"&MobileApp="+MobileApp+"&arrange=A&listYN=Y&eventStartDate=20241101&_type="+type);

    }catch(e){      
      console.log(e);
    }
  };

  useEffect(() => {
    Loging();
  },[]);


  return (
    <section id='main_conteiner'>
      <section className='left_box'></section> {/** 프로젝트 로고삽입 */}
      <section className='right_box'>
        <Festval_serch_details />
        <div className='card_list'>
          <Festval_list_card />
        </div>
      </section>
    </section>    
  );
}

export default App;
